"use client";

import React, { useRef } from "react";
import { motion, useScroll, useTransform } from "motion/react";
import { cn } from "@/lib/utils";

export interface ScrollTextLineItem {
  text: string;
  reverse?: boolean;
}

const DEFAULT_LINES: ScrollTextLineItem[] = [
  { text: "CREATIVE ENGINEERING", reverse: false },
  { text: "FLUID MOTION SYSTEMS", reverse: true },
  { text: "ALGORITHMIC VISUALS", reverse: false },
  { text: "NEXT-GEN INTERFACES", reverse: true },
];

export function ScrollTextLines({
  lines = DEFAULT_LINES,
  className,
  ...props
}: {
  lines?: ScrollTextLineItem[];
  className?: string;
}) {
  const containerRef = useRef<HTMLDivElement>(null);

  const { scrollYProgress } = useScroll({
    container: containerRef,
  });

  const forwardX = useTransform(scrollYProgress, [0, 1], ["0%", "-40%"]);
  const reverseX = useTransform(scrollYProgress, [0, 1], ["-40%", "0%"]);

  return (
    <div
      data-slot="scroll-text-lines"
      className={cn(
        "relative w-full max-w-xl mx-auto h-[480px] overflow-hidden rounded-3xl border border-neutral-200 dark:border-neutral-800 bg-neutral-950 shadow-2xl select-none flex flex-col justify-between p-6",
        className
      )}
      {...props}
    >
      <div className="flex items-center justify-between text-xs font-mono text-neutral-400 z-10">
        <span className="font-bold text-pink-500 uppercase tracking-wider">
          Dual Scroll Marquee
        </span>
        <span>Scroll vertically inside container</span>
      </div>

      <div
        ref={containerRef}
        className="h-full overflow-y-auto my-4"
      >
        <div className="relative h-[220vh] flex flex-col justify-center gap-6 sticky top-0 py-12">
          {lines.map((line, index) => {
            const x = line.reverse ? reverseX : forwardX;
            const isOutline = index % 2 === 1;

            return (
              <div
                key={index}
                className="overflow-hidden whitespace-nowrap py-1"
              >
                <motion.div
                  style={{ x }}
                  className="flex gap-6 will-change-transform"
                >
                  {Array.from({ length: 4 }).map((_, i) => (
                    <span
                      key={i}
                      className={cn(
                        "text-3xl sm:text-4xl font-black uppercase tracking-tight",
                        isOutline
                          ? "text-transparent [-webkit-text-stroke:1px_rgba(236,72,153,0.8)]"
                          : "text-white"
                      )}
                    >
                      {line.text} •
                    </span>
                  ))}
                </motion.div>
              </div>
            );
          })}
        </div>
      </div>

      <div className="text-[11px] font-mono text-neutral-500 text-center z-10">
        Inverted transform offsets driven by container scroll progress
      </div>
    </div>
  );
}
